ALTER TABLE "fundraising_contributions"
    ADD FOREIGN KEY("fundraising_id") REFERENCES "fundraisings"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "fundraising_contributions"
    ADD FOREIGN KEY("payer_id") REFERENCES "users"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "fundraising_contributions"
    ADD FOREIGN KEY("child_id") REFERENCES "children"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "classes"
    ADD FOREIGN KEY("logo_file_id") REFERENCES "files"("id")
        ON UPDATE NO ACTION ON DELETE SET NULL;
ALTER TABLE "class_memberships"
    ADD FOREIGN KEY("child_id") REFERENCES "children"("id")
        ON UPDATE NO ACTION ON DELETE CASCADE;
ALTER TABLE "wallets"
    ADD FOREIGN KEY("fundraising_id") REFERENCES "fundraisings"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "fundraising_contributions"
    ADD FOREIGN KEY("transaction_id") REFERENCES "transactions"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
ALTER TABLE "fundraising_contributions"
    ADD FOREIGN KEY("refund_transaction_id") REFERENCES "transactions"("id")
        ON UPDATE NO ACTION ON DELETE RESTRICT;
